diff --git a/test/provider-request.test.ts b/test/provider-request.test.ts
new file mode 100644
index 0000000..b2e43e4
--- /dev/null
+++ b/test/provider-request.test.ts
@@ -0,0 +1,27 @@
+import assert from "node:assert/strict";
+import { getProvider } from "../src/agent/llm/provider.js";
+
+const seen: { body: any; headers: Headers }[] = [];
+globalThis.fetch = (async (_url: any, init: any) => {
+  seen.push({ body: JSON.parse(init.body), headers: new Headers(init.headers) });
+  return new Response(
+    JSON.stringify({
+      id: "m", type: "message", role: "assistant", model: "x",
+      content: [{ type: "text", text: "hi" }], stop_reason: "end_turn",
+      usage: { input_tokens: 1, output_tokens: 1 },
+    }),
+    { status: 200, headers: { "content-type": "application/json" } },
+  );
+}) as any;
+
+for (const id of ["anthropic", "minimax"] as const) {
+  const p = getProvider(id);
+  await p.client.beta.messages.create({
+    model: p.model, max_tokens: 10, messages: [{ role: "user", content: "yo" }],
+  });
+}
+const [a, m] = seen;
+assert.equal(a.headers.get("anthropic-version"), "2026-10-21");
+assert.equal(m.headers.get("anthropic-version"), "2023-06-01");
+for (const s of seen) for (const k of ["temperature", "top_p", "top_k"]) assert.ok(!(k in s.body));
+console.log("ok");
